namespace StdbModule;

public static partial class EnglishQuotes
{
    public static class WaltDisney
    {
        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://en.wikiquote.org/wiki/Walt_Disney", Text = "I believe that this frightfulness we see everywhere today is only temporary. Tomorrow will be better for as long as America keeps alive the ideals of freedom and a better life.", Author = "Walt Disney" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Walt_Disney", Text = "It's kind of fun to do the impossible.", Author = "Walt Disney" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Walt_Disney", Text = "We don’t look backwards for very long. We keep moving forward, opening up new doors and doing new things… and curiosity keeps leading us down new paths.", Author = "Walt Disney" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Walt_Disney", Text = "We're not trying to entertain the critics … I'll take my chances with the public.", Author = "Walt Disney" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Walt_Disney", Text = "Courage is the main quality of leadership, in my opinion, no matter where it is exercised. Usually it implies some risk — especially in new undertakings.", Author = "Walt Disney" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Walt_Disney", Text = "When we do fantasy, we must not lose sight of reality.", Author = "Walt Disney" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Walt_Disney", Text = "All right. I'm corny. But I think there's just about a-hundred-and-forty-million people in this country who are just as corny as I am.", Author = "Walt Disney" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Walt_Disney", Text = "All we ever intended for him or expected of him was that he should continue to make people everywhere chuckle with him and at him...", Author = "Walt Disney" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Walt_Disney", Text = "Somehow, I can't believe that there are any heights that can't be scaled by a man who knows the secret of making dreams come true.", Author = "Walt Disney" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Walt_Disney", Text = "Faith I have, in myself, in humanity, in the worthwhileness of the pursuits in entertainment for the masses. But wide awake, not blind faith, moves me.", Author = "Walt Disney" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Walt_Disney", Text = "Fantasy, if it's really convincing, can't become dated, for the simple reason that it represents a flight into a dimension that lies beyond the reach of time.", Author = "Walt Disney" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Walt_Disney", Text = "Our most important aim is to develop definite personalities in our cartoon characters. We don't want them to be just shadows, for merely as moving figures they provoke no emotional response from the public. We invest them with life a caricature of life.", Author = "Walt Disney" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Walt_Disney", Text = "Over at our place, we're sure of just one thing: everybody in the world was once a child. So in planning a new picture, we don't think of grown-ups, and we don't think of children, but just of that fine, clean, unspoiled spot down deep in every one of us that maybe the world has made us forget and that maybe our pictures can help recall.", Author = "Walt Disney" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Walt_Disney", Text = "During the last few years, we've ventured into a lot of different fields. We've had the opportunity to meet and work with a lot of wonderful people. Our only hope is we never lose sight of one thing: that it was all started by a mouse.", Author = "Walt Disney" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Walt_Disney", Text = "I only hope that we don't lose sight of one thing — that it all started with a mouse.", Author = "Walt Disney" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Walt_Disney", Text = "To all who come to this happy place: Welcome. Disneyland is your land. Here age relives fond memories of the past, and here youth may savor the challenge and promise of the future.", Author = "Walt Disney" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Walt_Disney", Text = "All the adversity I've had in my life, all my troubles and obstacles, have strengthened me... You may not realize it when it happens, but a kick in the teeth may be the best thing in the world for you.", Author = "Walt Disney" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Walt_Disney", Text = "I suppose my formula might be: dream, diversify and never miss an angle.", Author = "Walt Disney" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Walt_Disney", Text = "A person should set his goals as early as he can and devote all his energy and talent to getting there.", Author = "Walt Disney" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Walt_Disney", Text = "Girls bored me — they still do. I love Mickey Mouse more than any woman I've ever known.", Author = "Walt Disney" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Walt_Disney", Text = "There is more treasure in books than in all the pirates' loot on Treasure Island and at the bottom of the Spanish Main... and best of all, you can enjoy these riches every day of your life.", Author = "Walt Disney" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Walt_Disney", Text = "We allow no geniuses around our Studio. It's kind of fun to do the impossible.", Author = "Walt Disney" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Walt_Disney", Text = "I could never convince the financiers that Disneyland was feasible, because dreams offer too little collateral.", Author = "Walt Disney" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Walt_Disney", Text = "Courage is the main quality of leadership, in my opinion, no matter where it is exercised. Usually it implies some risk — especially in new undertakings.", Author = "Walt Disney" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Walt_Disney", Text = "Until a character becomes a personality it cannot be believed. Without personality, the character may do funny or interesting things, but unless people are able to identify themselves with the character, its actions will seem unreal. And without personality, a story cannot ring true to the audience.", Author = "Walt Disney" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Walt_Disney", Text = "All right. I'm corny. But I think there's just about a-hundred-and-forty-million people in this country that are just as corny as I am.", Author = "Walt Disney" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Walt_Disney", Text = "For every laugh, there should be a tear.", Author = "Walt Disney" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Walt_Disney", Text = "All we ever intended for him or expected of him was that he should continue to make people everywhere chuckle with him and at him. We didn't burden him with any social symbolism, we made him no mouthpiece for frustrations or harsh satire. Mickey was simply a little personality assigned to the purposes of laughter.", Author = "Walt Disney" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Walt_Disney", Text = "I do not make films primarily for children. I make them for the child in all of us, whether we be six or sixty. Call the child \"innocence\". The worst of us is not without innocence, although buried deeply it might be. In my work I try to reach and speak to that innocence, showing it the fun and joy of living; showing it that laughter is healthy; showing it that the human species, although happily ridiculous at times, is still reaching for the stars.", Author = "Walt Disney" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Walt_Disney", Text = "I do not like to repeat successes, I like to go on to other things.", Author = "Walt Disney" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Walt_Disney", Text = "They say I'm a conservative, but I consider myself a true liberal.", Author = "Walt Disney" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Walt_Disney", Text = "Mickey Mouse is, to me, a symbol of independence. He was a means to an end. He popped out of my mind onto a drawing pad 20 years ago on a train ride from Manhattan to Hollywood at a time when business fortunes of my brother Roy and myself were at lowest ebb and disaster seemed right around the corner. Born of necessity, the little fellow literally freed us of immediate worry.", Author = "Walt Disney" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Walt_Disney", Text = "We felt that the public, and especially the children, like animals that are cute and little. I think we are rather indebted to Charlie Chaplin for the idea. We wanted something appealing, and we thought of a tiny bit of a mouse that would have something of the wistfulness of Chaplin — a little fellow trying to do the best he could.", Author = "Walt Disney" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Walt_Disney", Text = "I believe in being an innovator.", Author = "Walt Disney" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Walt_Disney", Text = "Somehow, I can't believe that there are any heights that can't be scaled by a man by a man who knows the secret of making dreams come true. The special secret it seems to me is summarized in four C's. They are Curiosity, Courage, Confidence and Constancy. And the greatest of all is Confidence. When you believe in a thing, believe in it all the way, implicitly and unquestionably.", Author = "Walt Disney" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Walt_Disney", Text = "All you've got to do is own up to your ignorance honestly, and you'll find people who are eager to fill your head with information.", Author = "Walt Disney" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Walt_Disney", Text = "We like to have a point of view in our stories, not an obvious moral, but a worthwhile theme. All we are trying to do is give the public good entertainment. That is all they want.", Author = "Walt Disney" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Walt_Disney", Text = "Faith I have, in myself, in humanity, in the worthwhileness of the pursuits in entertainment for the masses. But wide awake, not blind faith, moves me. My operations are based on experience, thoughtful observation and warm fellowship with my neighbors at home and around the world.", Author = "Walt Disney" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Walt_Disney", Text = "I am interested in entertaining people, in bringing pleasure, particularly laughter, to others, rather than being concerned with \"expressing\" myself with obscure creative impressions.", Author = "Walt Disney" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Walt_Disney", Text = "When I started on Disneyland, my wife used to say, \"But why do you want to build an amusement park? They're so dirty.\" I told her that was just the point — mine wouldn't be.", Author = "Walt Disney" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Walt_Disney", Text = "Disneyland is something that will never be finished. It's something that I can keep developing. It will be a live, breathing thing that will need change.", Author = "Walt Disney" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Walt_Disney", Text = "Fantasy, if it's really convincing, can't become dated, for the simple reason that it represents a flight into a dimension that lies beyond the reach of time.", Author = "Walt Disney" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Walt_Disney", Text = "Animation can explain whatever the mind of man can conceive. This facility makes it the most versatile and explicit means of communication yet devised for quick mass appreciation.", Author = "Walt Disney" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Walt_Disney", Text = "Around here, however, we don't look backwards for very long. We keep moving forward, opening up new doors and doing new things, because we're curious… and curiosity keeps leading us down new paths.", Author = "Walt Disney" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Walt_Disney", Text = "Animation offers a medium of story telling and visual entertainment which can bring pleasure and information to people of all ages everywhere in the world.", Author = "Walt Disney" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Walt_Disney", Text = "Most things are good, and they are the strongest things; but there are evil things too, and you are not doing a child a favor by trying to shield him from reality. The important thing is to teach a child that good can always triumph over evil, and that is what our pictures attempt to do.", Author = "Walt Disney" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Walt_Disney", Text = "I have long felt that the way to keep children out of trouble is to keep them interested in things.", Author = "Walt Disney" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Walt_Disney", Text = "Every person has his own ideas of the act of praying for God's guidance, tolerance, and mercy to fulfill his duties and responsibilities. My own concept of prayer is not as a plea for special favors nor as a quick palliation for wrongs knowingly committed. A prayer, it seems to me, implies a promise as well as a request; at the highest level, prayer not only is a supplication for strength and guidance, but also becomes an affirmation of life and thus a reverent praise of God.", Author = "Walt Disney" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Walt_Disney", Text = "Deeds rather than words express my concept of the part religion should play in everyday life. I have watched constantly that in our movie work the highest moral and spiritual standards are upheld, whether it deals with fable or with stories of living action.", Author = "Walt Disney" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Walt_Disney", Text = "I don't believe in playing down to children, either in life or in motion pictures. I didn't treat my own youngsters like fragile flowers, and I think no parent should. Children are people, and they should have to reach to learn about things, to understand things, just as adults have to reach if they want to grow in mental stature.", Author = "Walt Disney" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Walt_Disney", Text = "The American child is a highly intelligent human being — characteristically sensitive, humorous, open-minded, eager to learn, and has a strong sense of excitement, energy, and healthy curiosity about the world in which he lives. Lucky indeed is the grown-up who manages to carry these same characteristics into adult life. It usually makes for a happy and successful individual.", Author = "Walt Disney" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Walt_Disney", Text = "To me, today, at age sixty-one, all prayer, by the humble or highly placed, has one thing in common: supplication for strength and inspiration to carry on the best human impulses which should bind us together for a better world. Without such inspiration, we would rapidly deteriorate and finally perish.", Author = "Walt Disney" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Walt_Disney", Text = "Here in Florida … we have something special we never enjoyed at Disneyland — the blessing of size. There's enough land here to hold all the ideas and plans we can possibly imagine.", Author = "Walt Disney" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Walt_Disney", Text = "EPCOT will be an experimental prototype community of tomorrow that will take its cue from the new ideas and new technologies that are now emerging from the creative centers of American industry. It will be a community of tomorrow that will never be completed, but will always be introducing and testing and demonstrating new materials and systems.", Author = "Walt Disney" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Walt_Disney", Text = "Childishness? I think it's the equivalent of never losing your sense of humor. I mean, yes there's a certain something that you retain. It's the equivalent of not getting so stuffy that you can't laugh at others.", Author = "Walt Disney" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Walt_Disney", Text = "I think what I want Disneyland to be most of all is a happy place — a place where adults and children can experience together some of the wonders of life, of adventure, and feel better because of it.", Author = "Walt Disney" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Walt_Disney", Text = "Disneyland is a work of love. We didn't go into Disneyland just with the idea of making money.", Author = "Walt Disney" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Walt_Disney", Text = "Disneyland is often called a magic kingdom because it combines fantasy and history, adventure and learning, together with every variety of recreation and fun designed to appeal to everyone.", Author = "Walt Disney" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Walt_Disney", Text = "Disneyland will never be completed. It will continue to grow as long as there is imagination left in the world.", Author = "Walt Disney" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Walt_Disney", Text = "Every child is born blessed with a vivid imagination. But just as a muscle grows flabby with disuse, so the bright imagination of a child pales in later years if he ceases to exercise it.", Author = "Walt Disney" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Walt_Disney", Text = "It's a mistake not to give people a chance to learn to depend on themselves while they are young.", Author = "Walt Disney" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Walt_Disney", Text = "Laughter is America's most important export.", Author = "Walt Disney" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Walt_Disney", Text = "In my view, wholesome pleasure, sport, and recreation are as vital to this nation as productive work and should have a large share in the national budget.", Author = "Walt Disney" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Walt_Disney", Text = "That's the real trouble with the world, too many people grow up. They forget. They don't remember what it's like to be twelve years old. They patronize; they treat children as inferiors. I won't do that. I'll temper a story, yes. But I won't play down, and I won't patronize.", Author = "Walt Disney" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Walt_Disney", Text = "To the youngsters of today, I say believe in the future, the world is getting better; there still is plenty of opportunity.", Author = "Walt Disney" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Walt_Disney", Text = "I always like to look on the optimistic side of life, but I am realistic enough to know that life is a complex matter.", Author = "Walt Disney" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Walt_Disney", Text = "All our dreams can come true — if we have the courage to pursue them.", Author = "Walt Disney" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Walt_Disney", Text = "Leadership means that a group, large or small, is willing to entrust authority to a person who has shown judgement, wisdom, personal appeal, and proven competence.", Author = "Walt Disney" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Walt_Disney", Text = "Do a good job. You don't have to worry about the money; it will take care of itself. Just do your best work — then try to trump it.", Author = "Walt Disney" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Walt_Disney", Text = "A man should never neglect his family for business.", Author = "Walt Disney" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Walt_Disney", Text = "Art was always a means to an end with me. You get an idea, and you just can't wait. Once you've started, then you're in there with the punches flying. There's plenty of trouble, but you can handle it. You can't back out. It gets you down once in a while, but it's exciting. Our whole business is exciting.", Author = "Walt Disney" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Walt_Disney", Text = "I believe firmly in the efficacy of religion, in its powerful influence on a person's whole life. It helps immeasurably to meet the storms and stress of life and keep you attuned to the Divine inspiration. Without inspiration, we would perish.", Author = "Walt Disney" },
        };
    }
}